    vector<int> shortestDistanceColor(vector<int>& colors, vector<vector<int>>& queries) {
        vector<vector<int>> pos(4);
        for (int i = 0; i < (int)colors.size(); ++i) {
            pos[colors[i]].push_back(i);
        }
        vector<int> res;
        res.reserve(queries.size());
        for (const auto& q : queries) {
            int idx = q[0], c = q[1];
            const auto& arr = pos[c];
            if (arr.empty()) {
                res.push_back(-1);
                continue;
            }
            auto it = lower_bound(arr.begin(), arr.end(), idx);
            int best = INT_MAX;
            if (it != arr.end()) best = min(best, abs(*it - idx));
            if (it != arr.begin()) best = min(best, abs(*prev(it) - idx));
            res.push_back(best);
        }
        return res;
    }
};

import java.util.*;

class Solution {
    public List<Integer> shortestDistanceColor(int[] colors, int[][] queries) {
        List<Integer>[] pos = new List[4];
        for (int i = 1; i <= 3; i++) pos[i] = new ArrayList<>();
        for (int i = 0; i < colors.length; i++) {
            pos[colors[i]].add(i);
        }

        List<Integer> res = new ArrayList<>(queries.length);
        for (int[] q : queries) {
            int idx = q[0], c = q[1];
            List<Integer> arr = pos[c];
            if (arr.isEmpty()) {
                res.add(-1);
                continue;
            }
            int l = 0, r = arr.size();
            while (l < r) {
                int mid = l + (r - l) / 2;
                if (arr.get(mid) >= idx) r = mid;
                else l = mid + 1;
            }
            int best = Integer.MAX_VALUE;
            if (l < arr.size()) best = Math.min(best, Math.abs(arr.get(l) - idx));
            if (l > 0) best = Math.min(best, Math.abs(arr.get(l - 1) - idx));
            res.add(best);
        }
        return res;
    }
}

var shortestDistanceColor = function(colors, queries) {
    const pos = { 1: [], 2: [], 3: [] };
    for (let i = 0; i < colors.length; i++) {
        pos[colors[i]].push(i);
    }

    return queries.map(([idx, c]) => {
        const arr = pos[c];
        if (!arr || arr.length === 0) return -1;
        let l = 0, r = arr.length;
        while (l < r) {
            const mid = Math.floor((l + r) / 2);
            if (arr[mid] >= idx) r = mid;
            else l = mid + 1;
        }
        let best = Infinity;
        if (l < arr.length) best = Math.min(best, Math.abs(arr[l] - idx));
        if (l > 0) best = Math.min(best, Math.abs(arr[l - 1] - idx));
        return best;
    });
